import React, { useMemo, useState } from "react";
import { SafeAreaView, ScrollView, StatusBar, StyleSheet, Text, TouchableOpacity, View, Image } from "react-native";
import data from "../../packages/shared/src/data.json";

const formatDate = value => new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(new Date(`${value}T12:00:00`));
const JourneyCard = ({ journey, onPress }) => <TouchableOpacity style={styles.card} onPress={onPress} activeOpacity={0.85}>
  <Image source={{ uri: journey.coverImage }} style={styles.cardImage} />
  <View style={styles.cardContent}><Text style={[styles.status, journey.status === "draft" && styles.draft]}>{journey.status}</Text><Text style={styles.cardTitle}>{journey.title}</Text><Text style={styles.muted}>{formatDate(journey.startDate)} – {formatDate(journey.endDate)} · {journey.travellers} travellers</Text><Text style={styles.description}>{journey.description}</Text><Text style={styles.link}>Open journey →</Text></View>
</TouchableOpacity>;

function Overview({ onJourney }) {
  return <ScrollView contentContainerStyle={styles.container}>
    <Text style={styles.eyebrow}>YOUR NEXT CHAPTER</Text><Text style={styles.title}>Travel with intention, return with peace.</Text><Text style={styles.subtitle}>{data.app.tagline}. Keep every important detail of your journey in one calm, clear place.</Text>
    <View style={styles.hero}><Image source={{ uri: data.destinations[0].image }} style={styles.heroImage} /><Text style={styles.heroText}>Every journey begins with a peaceful first step.</Text></View>
    <View style={styles.headingRow}><Text style={styles.heading}>Pilgrimage packages</Text><Text style={styles.link}>See all</Text></View>
    {data.journeys.filter(journey => journey.status !== "completed").map(journey => <JourneyCard key={journey.id} journey={journey} onPress={() => onJourney(journey.id)} />)}
    <Text style={styles.heading}>Holy cities and services</Text>
    {data.destinations.map(destination => <View style={styles.destination} key={destination.id}><Image source={{ uri: destination.image }} style={styles.destinationImage} /><View style={styles.destinationCopy}><Text style={styles.cardTitle}>{destination.name}</Text><Text style={styles.muted}>{destination.country}</Text><Text style={styles.description}>{destination.description}</Text></View></View>)}
  </ScrollView>;
}

function JourneyDetail({ journey, onBack }) {
  return <ScrollView contentContainerStyle={styles.container}><TouchableOpacity onPress={onBack}><Text style={styles.link}>← Back to overview</Text></TouchableOpacity><View style={styles.detailHero}><Image source={{ uri: journey.coverImage }} style={styles.detailImage} /><View style={styles.detailOverlay}><Text style={styles.status}>{journey.status}</Text><Text style={styles.detailTitle}>{journey.title}</Text><Text style={styles.detailDescription}>{journey.description}</Text></View></View><View style={styles.headingRow}><Text style={styles.heading}>Itinerary</Text><Text style={styles.muted}>{journey.itinerary.length} moments</Text></View>{journey.itinerary.map(item => <View style={styles.timeline} key={`${item.date}-${item.title}`}><Text style={styles.date}>{formatDate(item.date)}</Text><View><Text style={styles.cardTitle}>{item.title}</Text><Text style={styles.muted}>{item.location} · {item.type}</Text></View></View>)}</ScrollView>;
}

